package ir.orix.school.assessment.domain;
import java.math.BigDecimal; import jakarta.persistence.*; import ir.orix.school.identity.domain.UserAccount; import ir.orix.school.organization.domain.Tenant; import ir.orix.school.shared.persistence.AuditedEntity;
@Entity @Table(name="question_version",schema="school")
public class QuestionVersion extends AuditedEntity {
 @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_id") private Tenant tenant; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="question_id") private Question question; @Column(name="version_number",nullable=false) private int versionNumber; @Column(nullable=false,columnDefinition="TEXT") private String prompt; @Column(name="options_json",columnDefinition="TEXT") private String optionsJson; @Column(name="answer_key_json",columnDefinition="TEXT") private String answerKeyJson; @Column(columnDefinition="TEXT") private String explanation; @Column(name="default_points",nullable=false,precision=10,scale=2) private BigDecimal defaultPoints; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by") private UserAccount createdBy;
 protected QuestionVersion(){} public QuestionVersion(Tenant tenant,Question question,int version,String prompt,String optionsJson,String answerKeyJson,String explanation,BigDecimal points,UserAccount actor){this.tenant=tenant;this.question=question;this.versionNumber=version;this.prompt=prompt.strip();this.optionsJson=optionsJson;this.answerKeyJson=answerKeyJson;this.explanation=normalize(explanation);this.defaultPoints=points;this.createdBy=actor;} private static String normalize(String v){return v==null||v.isBlank()?null:v.strip();}
 public Question getQuestion(){return question;} public int getVersionNumber(){return versionNumber;} public String getPrompt(){return prompt;} public String getOptionsJson(){return optionsJson;} public String getAnswerKeyJson(){return answerKeyJson;} public String getExplanation(){return explanation;} public BigDecimal getDefaultPoints(){return defaultPoints;}
}
